def save(p,v):p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
def main():
    now=datetime.now(timezone.utc).isoformat();checkpoint=read(ROOT/'verification/resource-sync-checkpoint.json');sync=read(ROOT/'verification/biwn-resource-sync-checks.json');mcp=read(ROOT/'verification/resource-sync-MCP-check.json');assert mcp['status']=='fresh_installed_sync_CPU_and_unproved_readiness_scope_passed'
    source=ROOT/'projects/black-ice-white-noise/restoration'
